return {
  CAREER = "UL-Toxic型是由最终生命研发，专为毒理学研究而设计的人形。其具体立项时间未知，本身设计也与最终生命旗下的其它产品有着较大区别，被推测为具有浓厚实验性质的机型。UL-Toxic的研究方向存在极高的潜在安全风险，为防止意外，每台机型在投入使用前都需经过严格的安全认证，且只向具备特殊资质的机构销售。由于常年与大量剧毒物质接触，UL-Toxic在未经过严格消毒措施的情况下被严格禁止与外界来往。\n被命名为“贝拉德娜”的UL-Toxic型曾在最终生命第三生物制药研究所工作，然而后续因为意外事故而行踪不明，直到数年后才重新出现在云图计划的名单中。",
  INFOSTORY1 = "根据最终生命人形研发记录显示，第一台UL-Toxic的诞生可以追溯到2054年。起因是当时最终生命第三制药研究所正在进行六级剧毒药物研究，需要人形助理配合项目负责人处理剧毒植株样本。但该需求被最终生命搁置，直到后来代号“樊笼”的剧毒植物孤岛培育计划启动，UL-Toxic的研发才再次被提上日程。第一台UL-Toxic最终由第三制药研究所的弗莉达·F·霍恩海姆教授引入，协助进行项目研究。\n\n为了能够及时检验样本数据的准确性，UL-Toxic配备了强大的生物信息数据库。日常对样本植株的看护要求UL-Toxic具备耐心感性，为此最终生命对其加装了简易情感模块。但研究人员发现，该型号在实际运行过程中经常会出现情感模块崩溃的严重瑕疵。庞大的数据资源进入心智后严重抢占核心处理能力，变相导致情感模块运行不稳定。许多购买机构要求厂商履行售后义务，拆除机体情感模块。在顾客的强烈要求下，除第三制药研究所保有的第一台UL-Toxic外，后续生产的该机型几乎全部为没有感情的“实验机器”。",
  INFOSTORY2 = "弗莉达教授给第一台UL-Toxic起名为“贝拉德娜”。早期贝拉德娜被弗莉达教授留在身边负责植株培育和样本采集。教授也将自己毕生所学倾囊相授。研究员在与贝拉德娜相处过程中，发现她对人类行为展现出强烈好奇。她会询问人类每一个行为的意图，模仿人类进食、休息、娱乐，在无法得到满足时也会表现出焦躁。\n\n研究员们时常抱怨加装情感模块让贝拉德娜变得复杂，给科研实验造成了一定的负担，并希望能把贝拉德娜退回将冗余模块摘除。弗莉达教授否决了这项提议。\n“她需要理解冰冷数据背后的意义，由此产生对生命的敬畏和尊重。否则她只会变成毁灭人类的凶器。”\n\n随着项目开展，人工培育的低浓度毒液植株样本不再能满足实验需求。此时“樊笼”计划正缺少一位孤岛植物看护员。为“樊笼”计划而生的贝拉德娜，既熟悉毒理又擅长照顾植物，成为了看护员的不二人选。",
  INFOSTORY3 = "刚登岛时贝拉德娜并未表现出明显的不适，可连续不断的实验很快让她的心智承压濒临上限。岛屿上没有其他人可以交流，缺乏情绪疏导，贝拉德娜的情感模块接连报错，然而这些问题都被和她对接的研究员无视忽略。\n\n孤岛实验室发生事故后，为了避免“樊笼”项目被媒体曝光，最终生命切断了与贝拉德娜的联系，贝拉德娜遗落荒岛。一段时间后风波平息，岛屿土地上的毒性经过雨水反复冲刷也有所减弱。最终生命高层为了回收项目实验数据，派遣船只将贝拉德娜回收，素体废弃，心智数据上传云图。\n\n参与云图计划给予了贝拉德娜第二次生命。除了保存研究数据，她在现实中几乎没有任何价值。过去的一系列经历造就了贝拉德娜扭曲癫狂的性格，她难以信任他人，并且对人类表现出极强的憎恶。",
  INFOSTORY4 = "来到云端后，因为携带剧毒，贝拉德娜很少和其他智能体产生交流，习惯了荒岛生活的她将孤独当作常态。后来在流浪过程中，她遇到了身为草药师的桑格玛，两人第一次见面相当不愉快。贝拉德娜在桑格玛熬制药物的砂锅中加入了大量乌头，被桑格玛当场抓获。反复教育后仍不知悔改。秉持着对云端公共卫生安全负责的态度，桑格玛决定带她回阿卡迪亚。然而这样做只起到了反效果。在得知了庇护者的领导者是人类后，贝拉德娜便将其看做了检验毒药效果的实验体，投毒行为更为猖狂，不过这样的举动只持续了一段时间，大概在到达阿卡迪亚第二周时她就有所收敛。\n\n“桑格玛她啊，是真的会把人丢进草药锅里煮的。”还在浑身冒热气的贝拉德娜这样解释自己改邪归正的原因。\n\n尽管桑格玛自诩擅长“教育”，但为了让贝拉德娜融入庇护者，她依旧花费了大量时间。最终在桑格玛严厉与温柔双重交织的手段下，贝拉德娜渐渐敞开心扉，表现出了乖巧的一面——虽然仅仅是在桑格玛面前。也是在阿卡迪亚，贝拉德娜交到了自己的第一个朋友——前赛车手邦尼薇娅。两人因为同样排斥人类而相处甚欢。谢拉多次目睹生性孤僻的贝拉德娜和邦尼薇娅躲在餐厅角落，谈论一些人类虐待外星人的不实谣言。",
  INFOSTORY5 = "经过庇护者高层批准，贝拉德娜被允许前往绿洲执行任务。在绿洲的时间中，除了和桑格玛待在一起，更多时候她会黏在教授身边。\n\n“哦呵呵，你们不会都被人类给骗了吧。人类善于伪装欺骗他人，表面善良的教授说不定哪天就会兽性大发。到时候绿洲的小可怜们想跑都来不及吧，嘿嘿嘿……”接受采访时她谨慎地躲在教授身后，嘴里却明目张胆说着教授的坏话。\n\n在绿洲生活一段时间后，贝拉德娜逐渐发现这里的独特之处。容纳了各色各样人形的绿洲中不乏和自己志趣相投的人。医疗部的芙洛伦就是其中之一，两人就“如何美观优雅地捆绑”进行了多次深入探讨。就二人所说，这些讨论“获取了相当有益的成果”。\n\n不论在阿卡迪亚还是绿洲，贝拉德娜的生活都比以前充实丰富。她也逐渐展现出了与以往的乖僻不同的一面，监护人桑格玛对此表示十分满意。"
}
